#!/usr/bin/env python3
"""Compact raw protocol smoke tests for LSP and DAP.

This file bundles the old common/lsp/dap helpers into one entry point so the
VS Code test harness stays small without changing the actual protocol checks.
"""
import argparse
import pathlib
import sys
import types

SOURCES = {
  "common.py": "#!/usr/bin/env python3\n\"\"\"Shared helpers for the Nytrix VS Code smoke tests.\"\"\"\n\nimport os\nimport pathlib\nimport shutil\nimport subprocess\n\nTEST_DIR = pathlib.Path(__file__).resolve().parent\n\n\ndef _resolve_env_path(name):\n    value = os.environ.get(name)\n    return pathlib.Path(value).expanduser().resolve() if value else None\n\n\ndef _walk_up(starts):\n    seen = set()\n    for start in starts:\n        if not start:\n            continue\n        current = pathlib.Path(start).expanduser().resolve()\n        for candidate in (current, *current.parents):\n            key = str(candidate)\n            if key in seen:\n                continue\n            seen.add(key)\n            yield candidate\n\n\ndef is_repo_root(path):\n    return (path / \"lib\").exists() and ((path / \"make\").exists() or (path / \"build\" / \"release\").exists())\n\n\ndef is_extension_root(path):\n    return (\n        (path / \"package.json\").exists()\n        and (path / \"src\" / \"extension.js\").exists()\n        and (path / \"nytrix.tmLanguage.json\").exists()\n    )\n\n\ndef find_repo_root():\n    env_root = _resolve_env_path(\"NYTRIX_REPO_ROOT\")\n    if env_root and (is_repo_root(env_root) or (env_root / \"lib\").exists()):\n        return env_root\n\n    starts = [pathlib.Path.cwd(), TEST_DIR, pathlib.Path.home() / \"nytrix\"]\n    candidates = []\n    for candidate in _walk_up(starts):\n        if (candidate / \"tmp\" / \"projects\" / \"vscode-nytrix\").exists() and (candidate / \"lib\").exists():\n            candidates.append(candidate)\n        elif is_repo_root(candidate):\n            candidates.append(candidate)\n\n    for binary in (\"ny-lsp\", \"ny\"):\n        for candidate in candidates:\n            if (candidate / \"build\" / \"release\" / binary).exists():\n                return candidate\n    if candidates:\n        return candidates[0]\n    return TEST_DIR.parents[3]\n\n\ndef find_extension_root(repo_root=None):\n    env_root = _resolve_env_path(\"NYTRIX_VSCODE_EXTENSION_ROOT\")\n    if env_root and is_extension_root(env_root):\n        return env_root\n\n    repo_root = repo_root or find_repo_root()\n    repo_candidate = repo_root / \"tmp\" / \"projects\" / \"vscode-nytrix\"\n    if is_extension_root(repo_candidate):\n        return repo_candidate\n\n    for candidate in _walk_up([TEST_DIR, pathlib.Path.cwd()]):\n        if is_extension_root(candidate):\n            return candidate\n    return TEST_DIR.parent\n\n\ndef default_tool(env_names, repo_rel, path_name, repo_root=None):\n    if isinstance(env_names, str):\n        env_names = [env_names]\n    for name in env_names:\n        value = os.environ.get(name)\n        if value:\n            return value\n    repo_root = repo_root or find_repo_root()\n    repo_candidate = repo_root / repo_rel\n    if repo_candidate.exists():\n        return str(repo_candidate)\n    found = shutil.which(path_name)\n    return found or str(repo_candidate)\n\n\ndef require_tool(value, label, *, env_hint=None):\n    if not value:\n        raise SystemExit(f\"{label} is not configured\")\n    if os.path.isabs(value) or os.sep in value:\n        if os.path.exists(value):\n            return value\n        hint = f\"; set {env_hint}\" if env_hint else \"\"\n        raise SystemExit(f\"{label} not found at {value}{hint}\")\n    found = shutil.which(value)\n    if found:\n        return found\n    hint = f\"; set {env_hint}\" if env_hint else \"\"\n    raise SystemExit(f\"{label} not found on PATH{hint}\")\n\n\ndef run(cmd, **kwargs):\n    timeout = kwargs.pop(\"timeout\", 20)\n    return subprocess.run(cmd, check=True, text=True, capture_output=True, timeout=timeout, **kwargs)\n\n\ndef maybe_run(cmd, **kwargs):\n    timeout = kwargs.pop(\"timeout\", 20)\n    return subprocess.run(cmd, check=False, text=True, capture_output=True, timeout=timeout, **kwargs)\n\n\ndef assert_true(cond, message):\n    if not cond:\n        raise AssertionError(message)\n",
  "lsp_smoke.py": "#!/usr/bin/env python3\nimport argparse\nimport json\nimport os\nimport pathlib\nimport subprocess\nimport tempfile\n\n\nfrom common import assert_true, default_tool, find_repo_root, require_tool\n\n\nREPO_ROOT = find_repo_root()\n\n\ndef default_lsp_path():\n    return default_tool([\"NYTRIX_LSP_BIN\", \"NYTRIX_LSP\"], pathlib.Path(\"build\") / \"release\" / \"ny-lsp\", \"ny-lsp\", REPO_ROOT)\n\n\nclass LspClient:\n    def __init__(self, exe):\n        self.proc = subprocess.Popen(\n            [exe],\n            stdin=subprocess.PIPE,\n            stdout=subprocess.PIPE,\n            stderr=subprocess.PIPE,\n            text=False,\n        )\n        self.next_id = 1\n\n    def close(self):\n        try:\n            self.notify(\"exit\", {})\n        except Exception:\n            pass\n        try:\n            self.proc.kill()\n        except Exception:\n            pass\n\n    def _write(self, payload):\n        body = json.dumps(payload, separators=(\",\", \":\")).encode(\"utf-8\")\n        header = f\"Content-Length: {len(body)}\\r\\n\\r\\n\".encode(\"ascii\")\n        self.proc.stdin.write(header)\n        self.proc.stdin.write(body)\n        self.proc.stdin.flush()\n\n    def notify(self, method, params):\n        self._write({\"jsonrpc\": \"2.0\", \"method\": method, \"params\": params})\n\n    def request(self, method, params):\n        req_id = self.next_id\n        self.next_id += 1\n        self._write({\"jsonrpc\": \"2.0\", \"id\": req_id, \"method\": method, \"params\": params})\n        notifications = []\n        while True:\n            msg = self.read_message()\n            if msg.get(\"id\") == req_id:\n                return msg, notifications\n            notifications.append(msg)\n\n    def read_message(self):\n        headers = {}\n        while True:\n            line = self.proc.stdout.readline()\n            if not line:\n                raise RuntimeError(self.proc.stderr.read().decode(\"utf-8\", \"replace\") or \"ny-lsp exited unexpectedly\")\n            if line in (b\"\\r\\n\", b\"\\n\"):\n                break\n            key, _, value = line.decode(\"ascii\").partition(\":\")\n            headers[key.strip().lower()] = value.strip()\n        length = int(headers[\"content-length\"])\n        body = self.proc.stdout.read(length)\n        return json.loads(body.decode(\"utf-8\"))\n\n\ndef normalized_signature_text(text):\n    return text.replace(\"():\", \"()\")\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument(\"--ny-lsp\", default=default_lsp_path())\n    args = ap.parse_args()\n    args.ny_lsp = require_tool(args.ny_lsp, \"ny-lsp\", env_hint=\"--ny-lsp or NYTRIX_LSP_BIN\")\n\n    with tempfile.TemporaryDirectory(prefix=\"ny-lsp-smoke-\") as td:\n        std_path = os.path.join(td, \"hover_test.ny\")\n        refs_path = os.path.join(td, \"refs_test.ny\")\n        bad_path = os.path.join(td, \"imports_bad.ny\")\n        std_text = \"use std.os\\nuse std.os.path\\n\\nprint(arch())\\nprint(sep())\\n\"\n        refs_text = (\n            \"fn local_sum(int a, int b) int { a + b }\\n\"\n            \"def first = local_sum(1, 2)\\n\"\n            \"def second = local_sum(3, 4)\\n\"\n        )\n        bad_text = \"use std *\\nuse std.core(print)\\n\"\n        for path, text in ((std_path, std_text), (refs_path, refs_text), (bad_path, bad_text)):\n            with open(path, \"w\", encoding=\"utf-8\") as f:\n                f.write(text)\n\n        client = LspClient(args.ny_lsp)\n        try:\n            init, _ = client.request(\"initialize\", {})\n            caps = init[\"result\"][\"capabilities\"]\n            assert_true(caps.get(\"hoverProvider\") is True, \"hoverProvider missing\")\n            assert_true(caps.get(\"definitionProvider\") is True, \"definitionProvider missing\")\n            assert_true(caps.get(\"referencesProvider\") is True, \"referencesProvider missing\")\n            assert_true(caps.get(\"documentSymbolProvider\") is True, \"documentSymbolProvider missing\")\n\n            client.notify(\n                \"textDocument/didOpen\",\n                {\"textDocument\": {\"uri\": f\"file://{std_path}\", \"languageId\": \"nytrix\", \"version\": 1, \"text\": std_text}},\n            )\n            client.notify(\n                \"textDocument/didOpen\",\n                {\"textDocument\": {\"uri\": f\"file://{refs_path}\", \"languageId\": \"nytrix\", \"version\": 1, \"text\": refs_text}},\n            )\n            client.notify(\n                \"textDocument/didOpen\",\n                {\"textDocument\": {\"uri\": f\"file://{bad_path}\", \"languageId\": \"nytrix\", \"version\": 1, \"text\": bad_text}},\n            )\n\n            notes = []\n            while len(notes) < 3:\n                notes.append(client.read_message())\n            diag_by_uri = {}\n            for note in notes:\n                if note.get(\"method\") == \"textDocument/publishDiagnostics\":\n                    diag_by_uri[note[\"params\"][\"uri\"]] = note[\"params\"][\"diagnostics\"]\n\n            bad_diags = diag_by_uri.get(f\"file://{bad_path}\", [])\n            codes = {d.get(\"code\") for d in bad_diags}\n            assert_true(\"NYSYN1001\" in codes, \"legacy import diagnostic missing\")\n            assert_true(\"NYSYN1002\" in codes, \"compact import diagnostic missing\")\n\n            hover, _ = client.request(\n                \"textDocument/hover\",\n                {\"textDocument\": {\"uri\": f\"file://{std_path}\"}, \"position\": {\"line\": 3, \"character\": 7}},\n            )\n            hover_value = hover[\"result\"][\"contents\"][\"value\"]\n            assert_true(\"fn std.os.arch()\" in normalized_signature_text(hover_value), \"hover for arch() is wrong\")\n            assert_true(\"`str`\" in hover_value or \" str\" in hover_value, \"hover for arch() return type is wrong\")\n\n            definition_arch, _ = client.request(\n                \"textDocument/definition\",\n                {\"textDocument\": {\"uri\": f\"file://{std_path}\"}, \"position\": {\"line\": 3, \"character\": 7}},\n            )\n            arch_uri = definition_arch[\"result\"][\"uri\"]\n            assert_true(\"/lib/os/\" in arch_uri and arch_uri.endswith(\".ny\"), \"arch() definition path is wrong\")\n\n            definition_sep, _ = client.request(\n                \"textDocument/definition\",\n                {\"textDocument\": {\"uri\": f\"file://{std_path}\"}, \"position\": {\"line\": 4, \"character\": 7}},\n            )\n            assert_true(definition_sep[\"result\"][\"uri\"].endswith(\"/lib/os/path.ny\"), \"sep() definition path is wrong\")\n\n            completion, _ = client.request(\n                \"textDocument/completion\",\n                {\"textDocument\": {\"uri\": f\"file://{std_path}\"}, \"position\": {\"line\": 3, \"character\": 7}},\n            )\n            labels = {item[\"label\"] for item in completion[\"result\"][\"items\"]}\n            assert_true(\"print\" in labels, \"builtin completion missing\")\n            assert_true(\"std.os.prim.arch\" in labels, \"stdlib completion missing arch\")\n\n            signature, _ = client.request(\n                \"textDocument/signatureHelp\",\n                {\"textDocument\": {\"uri\": f\"file://{std_path}\"}, \"position\": {\"line\": 3, \"character\": 11}},\n            )\n            sig_label = signature[\"result\"][\"signatures\"][0][\"label\"]\n            assert_true(\"fn std.os.arch()\" in normalized_signature_text(sig_label), \"signature help for arch() is wrong\")\n\n            doc_symbols, _ = client.request(\n                \"textDocument/documentSymbol\",\n                {\"textDocument\": {\"uri\": f\"file://{refs_path}\"}},\n            )\n            names = {item[\"name\"] for item in doc_symbols[\"result\"]}\n            assert_true(\"local_sum\" in names, \"document symbols missing local_sum\")\n            for item in doc_symbols[\"result\"]:\n                rng = item[\"range\"]\n                sel = item[\"selectionRange\"]\n                assert_true(\n                    (sel[\"start\"][\"line\"], sel[\"start\"][\"character\"]) >= (rng[\"start\"][\"line\"], rng[\"start\"][\"character\"])\n                    and (sel[\"end\"][\"line\"], sel[\"end\"][\"character\"]) <= (rng[\"end\"][\"line\"], rng[\"end\"][\"character\"]),\n                    f\"selectionRange escaped full range for {item['name']}\",\n                )\n\n            refs, _ = client.request(\n                \"textDocument/references\",\n                {\"textDocument\": {\"uri\": f\"file://{refs_path}\"}, \"position\": {\"line\": 0, \"character\": 4}, \"context\": {\"includeDeclaration\": True}},\n            )\n            assert_true(len(refs[\"result\"]) >= 3, \"references for local_sum are incomplete\")\n\n            ws, _ = client.request(\"workspace/symbol\", {\"query\": \"arch\"})\n            ws_names = {item[\"name\"] for item in ws[\"result\"]}\n            assert_true(\"std.os.prim.arch\" in ws_names, \"workspace symbol search missing arch\")\n            assert_true(client.proc.poll() is None, \"ny-lsp died before smoke test finished\")\n\n            print(\"lsp smoke: ok\")\n        finally:\n            client.close()\n\n\nif __name__ == \"__main__\":\n    main()\n",
  "dap_smoke.py": "#!/usr/bin/env python3\nimport argparse\nimport json\nimport os\nimport pathlib\nimport shutil\nimport subprocess\nimport tempfile\nimport time\n\nfrom common import assert_true, default_tool, find_extension_root, find_repo_root, require_tool\n\n\nREPO_ROOT = find_repo_root()\nEXT_ROOT = find_extension_root(REPO_ROOT)\n\n\ndef encode_message(payload):\n    body = json.dumps(payload, separators=(\",\", \":\")).encode(\"utf-8\")\n    header = f\"Content-Length: {len(body)}\\r\\n\\r\\n\".encode(\"ascii\")\n    return header + body\n\n\ndef decode_messages(blob):\n    messages = []\n    offset = 0\n    while offset < len(blob):\n        header_end = blob.find(b\"\\r\\n\\r\\n\", offset)\n        if header_end < 0:\n            break\n        header = blob[offset:header_end].decode(\"ascii\", \"replace\")\n        length = None\n        for line in header.split(\"\\r\\n\"):\n            if line.lower().startswith(\"content-length:\"):\n                length = int(line.split(\":\", 1)[1].strip())\n                break\n        if length is None:\n            raise RuntimeError(\"DAP output missing Content-Length header\")\n        body_start = header_end + 4\n        body_end = body_start + length\n        body = blob[body_start:body_end]\n        messages.append(json.loads(body.decode(\"utf-8\")))\n        offset = body_end\n    return messages\n\n\ndef send_request(proc, seq, command, arguments=None):\n    proc.stdin.write(encode_message({\n        \"seq\": seq,\n        \"type\": \"request\",\n        \"command\": command,\n        \"arguments\": arguments or {},\n    }))\n    proc.stdin.flush()\n\n\ndef response_for(messages, seq, command):\n    for msg in messages:\n        if msg.get(\"type\") == \"response\" and msg.get(\"request_seq\") == seq and msg.get(\"command\") == command:\n            return msg\n    return None\n\n\ndef events_named(messages, name):\n    return [msg for msg in messages if msg.get(\"type\") == \"event\" and msg.get(\"event\") == name]\n\n\ndef output_text_for(messages):\n    return \"\\n\".join(msg.get(\"body\", {}).get(\"output\", \"\") for msg in events_named(messages, \"output\"))\n\n\ndef run_auto_entry_smoke(args):\n    with tempfile.TemporaryDirectory(prefix=\"nytrix-debug-auto-entry-\") as td:\n        program = os.path.join(td, \"script_debug.ny\")\n        out_dir = os.path.join(td, \"out\")\n        with open(program, \"w\", encoding=\"utf-8\") as f:\n            f.write(\n                \"def config_json = \\\"{\\\\\\\"name\\\\\\\":\\\\\\\"Nytrix\\\\\\\",\\\\\\\"fps\\\\\\\":10000,\\\\\\\"ok\\\\\\\":true}\\\"\\n\"\n                \"def scene_xml = \\\"<scene arch=\\\\\\\"x86_64\\\\\\\"><fps>10000</fps></scene>\\\"\\n\"\n                \"print(config_json)\\n\"\n                \"print(scene_xml)\\n\"\n            )\n\n        proc = subprocess.Popen(\n            [args.node, args.adapter],\n            stdin=subprocess.PIPE,\n            stdout=subprocess.PIPE,\n            stderr=subprocess.PIPE,\n            text=False,\n        )\n        try:\n            seq = 1\n            send_request(proc, seq, \"initialize\", {\n                \"adapterID\": \"nytrix\",\n                \"pathFormat\": \"path\",\n                \"linesStartAt1\": True,\n                \"columnsStartAt1\": True,\n                \"supportsRunInTerminalRequest\": False,\n            })\n            init_seq = seq\n            seq += 1\n            time.sleep(0.1)\n\n            send_request(proc, seq, \"launch\", {\n                \"program\": program,\n                \"cwd\": td,\n                \"stopOnEntry\": False,\n                \"nyPath\": args.ny,\n                \"gdbPath\": args.gdb,\n                \"outputDir\": out_dir,\n                \"trace\": False,\n                \"compilerArgs\": [],\n                \"debugLocals\": False,\n            })\n            launch_seq = seq\n            seq += 1\n            time.sleep(0.2)\n\n            send_request(proc, seq, \"configurationDone\", {})\n            cfg_seq = seq\n            seq += 1\n            time.sleep(5.0)\n\n            send_request(proc, seq, \"stackTrace\", {\"threadId\": 1})\n            stack_seq = seq\n            seq += 1\n            time.sleep(0.1)\n\n            send_request(proc, seq, \"continue\", {\"threadId\": 1})\n            cont_seq = seq\n            seq += 1\n            time.sleep(1.5)\n\n            send_request(proc, seq, \"disconnect\", {\"restart\": False})\n            disconnect_seq = seq\n            seq += 1\n            proc.stdin.close()\n\n            stdout, stderr = proc.communicate(timeout=120.0)\n            messages = decode_messages(stdout)\n            stderr_text = stderr.decode(\"utf-8\", \"replace\")\n\n            init = response_for(messages, init_seq, \"initialize\")\n            assert_true(init and init.get(\"success\") is True, f\"auto-entry initialize failed: {stderr_text}\")\n\n            launch = response_for(messages, launch_seq, \"launch\")\n            assert_true(launch and launch.get(\"success\") is True, f\"auto-entry launch failed: {launch!r} {output_text_for(messages)} {stderr_text}\")\n\n            cfg = response_for(messages, cfg_seq, \"configurationDone\")\n            assert_true(cfg and cfg.get(\"success\") is True, \"auto-entry configurationDone failed\")\n\n            stopped = events_named(messages, \"stopped\")\n            assert_true(stopped, \"auto-entry launch never stopped\")\n\n            stack = response_for(messages, stack_seq, \"stackTrace\")\n            frames = stack.get(\"body\", {}).get(\"stackFrames\", []) if stack else []\n            assert_true(frames, \"auto-entry stack trace is empty\")\n            top = frames[0]\n            assert_true(top.get(\"source\", {}).get(\"path\") == program, f\"auto-entry top source mismatch: {top!r}\")\n            assert_true(int(top.get(\"line\", 0)) >= 1, f\"auto-entry top line invalid: {top!r}\")\n            assert_true(\"_ny_top_entry\" not in top.get(\"name\", \"\"), f\"auto-entry leaked internal frame name: {top!r}\")\n            assert_true(stack.get(\"body\", {}).get(\"totalFrames\") == 1, f\"auto-entry should hide runtime scaffolding by default: {stack!r}\")\n\n            cont = response_for(messages, cont_seq, \"continue\")\n            assert_true(cont and cont.get(\"success\") is True, \"auto-entry continue failed\")\n\n            disconnect = response_for(messages, disconnect_seq, \"disconnect\")\n            assert_true(disconnect and disconnect.get(\"success\") is True, \"auto-entry disconnect failed\")\n\n            output_text = output_text_for(messages)\n            assert_true(\"[auto-break]\" in output_text, \"auto-entry launch did not report the temporary entry breakpoint\")\n            assert_true(\"runtime frame hidden\" in output_text, \"auto-entry backtrace did not report hidden runtime frames\")\n            assert_true(events_named(messages, \"terminated\"), \"auto-entry launch never terminated\")\n        finally:\n            if proc.poll() is None:\n                proc.kill()\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument(\"--node\", default=\"node\")\n    ap.add_argument(\"--adapter\", default=os.environ.get(\"NYTRIX_DEBUG_ADAPTER\", str(EXT_ROOT / \"src\" / \"nytrixDebugAdapter.js\")))\n    ap.add_argument(\"--ny\", default=default_tool(\"NYTRIX_BIN\", pathlib.Path(\"build\") / \"release\" / \"ny\", \"ny\"))\n    ap.add_argument(\"--gdb\", default=os.environ.get(\"NYTRIX_GDB_BIN\") or os.environ.get(\"GDB_BIN\") or shutil.which(\"gdb\") or \"gdb\")\n    args = ap.parse_args()\n    args.node = require_tool(args.node, \"node\")\n    args.adapter = require_tool(args.adapter, \"adapter\", env_hint=\"NYTRIX_DEBUG_ADAPTER\")\n    args.ny = require_tool(args.ny, \"ny\", env_hint=\"NYTRIX_BIN\")\n    args.gdb = require_tool(args.gdb, \"gdb\", env_hint=\"NYTRIX_GDB_BIN or GDB_BIN\")\n\n    with tempfile.TemporaryDirectory(prefix=\"nytrix-debug-smoke-\") as td:\n        program = os.path.join(td, \"debug_test.ny\")\n        out_dir = os.path.join(td, \"out\")\n        with open(program, \"w\", encoding=\"utf-8\") as f:\n            f.write(\n                \"fn add_one(int value) int {\\n\"\n                \"   return value + 1\\n\"\n                \"}\\n\"\n                \"\\n\"\n                \"fn twice(int base) int {\\n\"\n                \"   def y = add_one(base)\\n\"\n                \"   print(y)\\n\"\n                \"   return y\\n\"\n                \"}\\n\"\n                \"\\n\"\n                \"fn main() int {\\n\"\n                \"   def x = 41\\n\"\n                \"   def y = twice(x)\\n\"\n                \"   print(y)\\n\"\n                \"   return 0\\n\"\n                \"}\\n\"\n            )\n\n        proc = subprocess.Popen(\n            [args.node, args.adapter],\n            stdin=subprocess.PIPE,\n            stdout=subprocess.PIPE,\n            stderr=subprocess.PIPE,\n            text=False,\n        )\n        try:\n            seq = 1\n            send_request(proc, seq, \"initialize\", {\n                \"adapterID\": \"nytrix\",\n                \"pathFormat\": \"path\",\n                \"linesStartAt1\": True,\n                \"columnsStartAt1\": True,\n                \"supportsRunInTerminalRequest\": False,\n            })\n            init_seq = seq\n            seq += 1\n            time.sleep(0.1)\n\n            send_request(proc, seq, \"launch\", {\n                \"program\": program,\n                \"cwd\": td,\n                \"stopOnEntry\": False,\n                \"nyPath\": args.ny,\n                \"gdbPath\": args.gdb,\n                \"outputDir\": out_dir,\n                \"trace\": False,\n                \"compilerArgs\": [\"--dwarf-version=5\"],\n                \"args\": [\"alpha\", \"beta\"],\n                \"env\": {\"NYTRIX_DEBUG_SMOKE_ENV\": \"nytrix-env-ok\"},\n                \"sourceFileMap\": {td: td},\n            })\n            launch_seq = seq\n            seq += 1\n            time.sleep(0.2)\n\n            send_request(proc, seq, \"setBreakpoints\", {\n                \"source\": {\"path\": program},\n                \"breakpoints\": [{\"line\": 7}],\n                \"lines\": [7],\n            })\n            bp_seq = seq\n            seq += 1\n            time.sleep(0.1)\n\n            send_request(proc, seq, \"configurationDone\", {})\n            cfg_seq = seq\n            seq += 1\n            time.sleep(3.0)\n\n            send_request(proc, seq, \"threads\", {})\n            threads_seq = seq\n            seq += 1\n            time.sleep(0.1)\n\n            send_request(proc, seq, \"stackTrace\", {\"threadId\": 1})\n            stack_seq = seq\n            seq += 1\n            time.sleep(0.1)\n\n            send_request(proc, seq, \"exceptionInfo\", {\"threadId\": 1})\n            exception_seq = seq\n            seq += 1\n            time.sleep(0.1)\n\n            send_request(proc, seq, \"loadedSources\", {})\n            loaded_seq = seq\n            seq += 1\n            time.sleep(0.1)\n\n            send_request(proc, seq, \"modules\", {})\n            modules_seq = seq\n            seq += 1\n            time.sleep(0.1)\n\n            send_request(proc, seq, \"scopes\", {\"frameId\": 1})\n            scopes_seq = seq\n            seq += 1\n            time.sleep(0.1)\n\n            send_request(proc, seq, \"evaluate\", {\"expression\": \"1 + 1\", \"frameId\": 1})\n            eval_seq = seq\n            seq += 1\n            time.sleep(0.1)\n\n            send_request(proc, seq, \"continue\", {\"threadId\": 1})\n            continue_seq = seq\n            seq += 1\n            time.sleep(2.0)\n\n            send_request(proc, seq, \"disconnect\", {\"restart\": False})\n            disconnect_seq = seq\n            seq += 1\n            proc.stdin.close()\n\n            stdout, stderr = proc.communicate(timeout=120.0)\n            messages = decode_messages(stdout)\n            stderr_text = stderr.decode(\"utf-8\", \"replace\")\n\n            init = response_for(messages, init_seq, \"initialize\")\n            assert_true(init and init.get(\"success\") is True, f\"initialize failed: {stderr_text}\")\n            caps = init.get(\"body\", {})\n            assert_true(caps.get(\"supportsConfigurationDoneRequest\") is True, \"configurationDone support missing\")\n            assert_true(caps.get(\"supportsLoadedSourcesRequest\") is True, \"loaded sources capability missing\")\n            assert_true(caps.get(\"supportsModulesRequest\") is True, \"modules capability missing\")\n\n            launch = response_for(messages, launch_seq, \"launch\")\n            assert_true(launch and launch.get(\"success\") is True, f\"launch failed: {launch!r} {output_text_for(messages)} {stderr_text}\")\n\n            bp_resp = response_for(messages, bp_seq, \"setBreakpoints\")\n            assert_true(bp_resp and bp_resp.get(\"success\") is True, \"setBreakpoints failed\")\n            bps = bp_resp.get(\"body\", {}).get(\"breakpoints\", [])\n            assert_true(len(bps) == 1, \"expected one source breakpoint result\")\n\n            cfg = response_for(messages, cfg_seq, \"configurationDone\")\n            assert_true(cfg and cfg.get(\"success\") is True, \"configurationDone failed\")\n\n            threads = response_for(messages, threads_seq, \"threads\")\n            assert_true(threads and len(threads.get(\"body\", {}).get(\"threads\", [])) >= 1, \"threads list is empty\")\n\n            stack = response_for(messages, stack_seq, \"stackTrace\")\n            frames = stack.get(\"body\", {}).get(\"stackFrames\", []) if stack else []\n            assert_true(frames, f\"stack trace is empty: {stack!r} {output_text_for(messages)}\")\n            top = frames[0]\n            frame_names = [frame.get(\"name\", \"\") for frame in frames]\n            assert_true(any(\"twice\" in name for name in frame_names), f\"stack trace missing twice(): {frame_names!r}\")\n            assert_true(any(\"main\" in name for name in frame_names), f\"stack trace missing main(): {frame_names!r}\")\n            assert_true(top.get(\"source\", {}).get(\"path\") == program, f\"top frame source path mismatch: {top!r}\")\n\n            scopes = response_for(messages, scopes_seq, \"scopes\")\n            scope_names = {scope.get(\"name\") for scope in scopes.get(\"body\", {}).get(\"scopes\", [])} if scopes else set()\n            assert_true(\"Arguments\" in scope_names and \"Locals\" in scope_names and \"Registers\" in scope_names, \"expected arguments/locals/register scopes\")\n\n            exception = response_for(messages, exception_seq, \"exceptionInfo\")\n            exception_details = (exception or {}).get(\"body\", {}).get(\"details\", {})\n            stack_text = exception_details.get(\"stackTrace\", \"\")\n            assert_true(\"twice\" in stack_text and \"main\" in stack_text, f\"exception backtrace is too thin: {stack_text!r}\")\n\n            loaded = response_for(messages, loaded_seq, \"loadedSources\")\n            loaded_paths = [src.get(\"path\") for src in (loaded or {}).get(\"body\", {}).get(\"sources\", [])]\n            assert_true(program in loaded_paths, f\"loadedSources missing program: {loaded_paths!r}\")\n\n            modules = response_for(messages, modules_seq, \"modules\")\n            module_names = [mod.get(\"name\") for mod in (modules or {}).get(\"body\", {}).get(\"modules\", [])]\n            assert_true(any(\"debug_test\" in (name or \"\") for name in module_names), f\"modules missing debug binary: {module_names!r}\")\n\n            evaluate = response_for(messages, eval_seq, \"evaluate\")\n            result = evaluate.get(\"body\", {}).get(\"result\") if evaluate else None\n            assert_true(result in (\"2\", \"0x2\"), f\"evaluate response is unexpected: {result!r}\")\n\n            cont = response_for(messages, continue_seq, \"continue\")\n            assert_true(cont and cont.get(\"success\") is True, \"continue failed\")\n\n            disconnect = response_for(messages, disconnect_seq, \"disconnect\")\n            assert_true(disconnect and disconnect.get(\"success\") is True, \"disconnect failed\")\n\n            assert_true(events_named(messages, \"initialized\"), \"initialized event missing\")\n            assert_true(events_named(messages, \"stopped\"), \"stopped event missing\")\n            assert_true(events_named(messages, \"terminated\"), \"terminated event missing\")\n            output_text = \"\\n\".join(msg.get(\"body\", {}).get(\"output\", \"\") for msg in events_named(messages, \"output\"))\n            assert_true(\"debug_test.ny\" in output_text, \"debug session output never referenced debug_test.ny\")\n            assert_true(\"alpha beta\" in output_text, \"debug launch output did not report program args\")\n            assert_true(\"NYTRIX_DEBUG_SMOKE_ENV\" in output_text, \"debug launch output did not report env key\")\n            assert_true(\"source-map\" in output_text and \"1 rule\" in output_text, \"debug launch output did not report source map\")\n            assert_true(\"--dwarf-version=5\" in output_text, \"debug launch output did not report DWARF compiler arg\")\n            assert_true(\"[backtrace]\" in output_text and \"twice\" in output_text, \"debug console backtrace output missing\")\n\n            run_auto_entry_smoke(args)\n            print(\"dap smoke: ok\")\n        finally:\n            if proc.poll() is None:\n                proc.kill()\n\n\nif __name__ == \"__main__\":\n    main()\n"
}
TEST_DIR = pathlib.Path(__file__).resolve().parent


def load_module(name):
    module = types.ModuleType(name)
    module.__file__ = str(TEST_DIR / f"{name}.py")
    module.__package__ = ""
    sys.modules[name] = module
    exec(compile(SOURCES[f"{name}.py"], module.__file__, "exec"), module.__dict__)
    return module


def main():
    parser = argparse.ArgumentParser(description="Nytrix VS Code raw protocol smoke tests")
    parser.add_argument("target", nargs="?", default="all", choices=("all", "lsp", "dap"))
    args, rest = parser.parse_known_args()

    load_module("common")
    targets = ["lsp", "dap"] if args.target == "all" else [args.target]
    for target in targets:
        module = load_module(f"{target}_smoke")
        old_argv = sys.argv[:]
        try:
            sys.argv = [str(TEST_DIR / f"{target}_smoke.py"), *rest]
            module.main()
        finally:
            sys.argv = old_argv


if __name__ == "__main__":
    main()
